	        UPDATE REPLIES 
               SET DEL_YN = 'Y'
                 , MDFY_DT = SYSDATE 
             WHERE ID = #{repliesId}
               and ARTICLE_ID = #{articleId}
               and DEL_YN = 'N'

UPDATE REPLIES
   SET RECOMMEND_CNT = RECOMMEND_CNT + 1
 WHERE ID = #{repliesId}
   and ARTICLE_ID = #{articleId}
   and DEL_YN = 'N'

UPDATE REPLIES
   SET CONTENT = #{modifyRepliesVO.content}
     , MDFY_DT = SYSDATE 
     , FILE_SET_ID = #{modifyRepliesVO.fileSetId}
 WHERE ARTICLE_ID = #{articleId}
   AND ID = #{repliesId}
   AND EMAIL = #{modifyRepliesVO.email}
   AND DEL_YN = 'N'
